"""Fibonacci implementations: iterative and memoized recursive."""


def fib_iterative(n):
    """Return the n-th Fibonacci number using iteration.

    fib(0) == 0, fib(1) == 1.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b


def fib_recursive(n, _memo=None):
    """Return the n-th Fibonacci number using memoized recursion.

    fib(0) == 0, fib(1) == 1.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n < 2:
        return n
    if _memo is None:
        _memo = {}
    if n in _memo:
        return _memo[n]
    _memo[n] = fib_recursive(n - 1, _memo) + fib_recursive(n - 2, _memo)
    return _memo[n]

