"""Matrix helpers: transpose and multiply for lists of lists.

A matrix is represented as a list of rows, where each row is a list of
numbers. All rows must have the same length.
"""


def _shape(m):
    """Return (rows, cols), validating that ``m`` is a rectangular matrix.

    Raises:
        ValueError: if ``m`` is empty or its rows have differing lengths.
    """
    if not m:
        raise ValueError("matrix must have at least one row")
    cols = len(m[0])
    if cols == 0:
        raise ValueError("matrix rows must have at least one column")
    for row in m:
        if len(row) != cols:
            raise ValueError("matrix rows must all have the same length")
    return len(m), cols


def transpose(m):
    """Return the transpose of matrix ``m``.

    The element at row ``i``, column ``j`` of ``m`` becomes the element at
    row ``j``, column ``i`` of the result.
    """
    rows, cols = _shape(m)
    return [[m[i][j] for i in range(rows)] for j in range(cols)]


def multiply(a, b):
    """Return the matrix product of ``a`` and ``b``.

    ``a`` must be an ``m`` x ``n`` matrix and ``b`` an ``n`` x ``p`` matrix;
    the result is ``m`` x ``p``.
    """
    a_rows, a_cols = _shape(a)
    b_rows, b_cols = _shape(b)
    if a_cols != b_rows:
        raise ValueError(
            "cannot multiply {0}x{1} matrix by {2}x{3} matrix".format(
                a_rows, a_cols, b_rows, b_cols
            )
        )
    return [
        [
            sum(a[i][k] * b[k][j] for k in range(a_cols))
            for j in range(b_cols)
        ]
        for i in range(a_rows)
    ]

